use std::collections::HashMap;

pub const OPERATION_FIELD: &str = "operation";
pub const COVERAGE_REQUIREMENT_FIELD: &str = "coverageRequirement";
pub const SUBMIT_OPERATION: &str = "submit-audit-unit";
pub const REQUIRED_COVERAGE: &str = "required";

pub struct SubmissionResult {
    pub accepted: bool,
}

pub fn submit_request(request: HashMap<&str, &str>) -> SubmissionResult {
    SubmissionResult {
        accepted: request.get(OPERATION_FIELD) == Some(&SUBMIT_OPERATION)
            && request.get(COVERAGE_REQUIREMENT_FIELD) == Some(&REQUIRED_COVERAGE),
    }
}

